// Genetics Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: crosses, probability, Hardy-Weinberg and molecular mechanisms.
import {q, mix} from './q.js';
const CAR='Carolina Genetics: A Guidebook for the HOSA Genetics Written Test';
const MEI='Reproduction, Mitosis and Meiosis', CLAS='Classical Genetics', CHR='Chromosomal Inheritance', EXP='Experimental Design and Model Organisms', MOL='Molecular Genetics', POP='Population Genetics', MOD='Modern Applications and Careers in Genetics';

export default {
 id:'genetics-1',
 event:'Genetics',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Carolina Genetics: A Guidebook for the HOSA Genetics Written Test',
 plan:[{area:MEI,weight:20},{area:CLAS,weight:20},{area:CHR,weight:10},{area:EXP,weight:15},{area:MOL,weight:15},{area:POP,weight:10},{area:MOD,weight:10}],
 questions:mix([
  q(MEI,'During which stage does crossing over between homologous chromosomes occur?','Prophase I',['Metaphase II','Anaphase I','Telophase II'],'B','In prophase I, homologous chromosomes pair (synapsis) and exchange segments, creating new combinations of alleles.',CAR),
  q(MEI,'During which stage do homologous chromosomes separate?','Anaphase I',['Anaphase II','Prophase I','Metaphase of mitosis'],'D','Homologs separate in anaphase I, halving the chromosome number. Sister chromatids separate in anaphase II and in mitotic anaphase.',CAR),
  q(MEI,'In mitosis, what separates during anaphase?','Sister chromatids',['Homologous chromosomes','Tetrads','Whole cells'],'A','Mitotic anaphase pulls sister chromatids to opposite poles so each daughter cell gets an identical set of chromosomes.',CAR),
  q(MEI,'What does mitosis produce from one diploid cell?','Two genetically identical diploid cells',['Four genetically different haploid cells','Two haploid gametes','One cell with twice the DNA'],'C','Mitosis is used for growth and repair. Meiosis produces four genetically different haploid cells.',CAR),
  q(MEI,'How many chromosomes are in a normal human egg or sperm cell?','23',['46','22','92'],'B','Gametes are haploid (n = 23). Fertilization restores the diploid number of 46.',CAR),
  q(MEI,'The random orientation of homologous pairs at the metaphase plate during meiosis I produces genetic variation by:','Independent assortment',['Crossing over in prophase I','Mutation','Nondisjunction'],'D','Each pair lines up independently, so many combinations of maternal and paternal chromosomes are possible (2²³ in humans).',CAR),
  q(MEI,'How does cytokinesis in plant cells differ from that in animal cells?','Plant cells form a cell plate',['Plant cells form a cleavage furrow','Plant cells skip cytokinesis','Plant cells divide their nucleus twice'],'A','A rigid cell wall prevents pinching, so vesicles build a cell plate that becomes a new wall. Animal cells pinch apart with a cleavage furrow.',CAR),
  q(MEI,'Which protein acts at the G1 checkpoint and can stop the cell cycle if DNA is damaged?','p53',['Cyclin-dependent kinase only','Hemoglobin','Actin'],'C','p53, a tumor suppressor, halts division for repair or triggers apoptosis. Mutations in p53 are common in cancers.',CAR),
  q(MEI,'Failure of chromosomes to separate properly during meiosis is called:','Nondisjunction',['Crossing over','Translocation','Replication'],'B','Nondisjunction produces gametes with an extra or missing chromosome, leading to conditions such as trisomy 21.',CAR),
  q(MEI,'How many genetically unique cells does one round of meiosis produce from a single parent cell?','Four',['One','Two','Eight'],'D','Meiosis I and II produce four haploid cells. In human females, only one becomes an egg; the others become polar bodies.',CAR),
  q(CLAS,'Two heterozygous tall plants (Tt × Tt) are crossed. Tall is dominant. What phenotypic ratio is expected?','3 tall : 1 short',['1 tall : 1 short','1 tall : 2 medium : 1 short','All tall'],'A','The genotypes are 1 TT : 2 Tt : 1 tt. Three of four offspring carry at least one T and are tall.',CAR),
  q(CLAS,'A dihybrid cross of AaBb × AaBb with complete dominance gives which phenotypic ratio?','9 : 3 : 3 : 1',['1 : 1 : 1 : 1','3 : 1','1 : 2 : 1'],'C','With independent assortment, two monohybrid 3:1 ratios combine: (3:1)(3:1) = 9:3:3:1.',CAR),
  q(CLAS,'An organism with a dominant phenotype is crossed with a homozygous recessive organism to find its genotype. What is this called?','A test cross',['A back cross with the dominant parent','A dihybrid cross','A reciprocal cross'],'B','If any offspring show the recessive trait, the unknown parent must be heterozygous.',CAR),
  q(CLAS,'In the cross AaBbCc × AaBbCc, what is the probability of an aabbcc offspring?','1/64',['1/8','1/16','1/32'],'D','Each gene has a 1/4 chance of aa. Multiply for independent genes: 1/4 × 1/4 × 1/4 = 1/64.',CAR),
  q(CLAS,'Red snapdragons crossed with white snapdragons produce all pink offspring. If two pink plants are crossed, what ratio is expected?','1 red : 2 pink : 1 white',['3 red : 1 white only','All pink offspring','9 : 3 : 3 : 1'],'A','This is incomplete dominance; heterozygotes are intermediate. A cross of two heterozygotes gives a 1:2:1 phenotypic ratio.',CAR),
  q(CLAS,'A person with type AB blood expresses both A and B antigens fully. This is an example of:','Codominance',['Incomplete dominance','Epistasis','Sex linkage'],'C','In codominance, both alleles are fully expressed in the heterozygote. In incomplete dominance, the phenotype is a blend.',CAR),
  q(CLAS,'A mother with type A blood (IAi) and a father with type B blood (IBi) have a child. What is the probability the child has type O blood?','1/4',['0','1/2','3/4'],'B','Each parent passes i with probability 1/2, so ii (type O) = 1/2 × 1/2 = 1/4.',CAR),
  q(CLAS,'A woman who carries an X-linked recessive disorder has children with an unaffected man. What is the chance that each son is affected?','50%',['0%','25%','100%'],'D','Sons get their X from their mother, who has one normal and one affected X. Daughters get the father’s normal X, so they may be carriers but are not affected.',CAR),
  q(CLAS,'In Labrador retrievers, a gene for pigment deposition determines whether the black or brown coat gene is expressed at all. What is this?','Epistasis',['Codominance','Polyploidy','Linkage'],'A','In epistasis, one gene masks the effect of another. Dogs homozygous ee are yellow regardless of their B/b genotype.',CAR),
  q(CLAS,'In a pedigree, a trait appears in every generation, and affected individuals usually have an affected parent. Which inheritance pattern is most likely?','Autosomal dominant',['Autosomal recessive','X-linked recessive','Mitochondrial only'],'C','Dominant traits rarely skip generations. Autosomal recessive traits often skip generations and appear in children of unaffected carriers.',CAR),
  q(CHR,'Which chromosome abnormality causes Down syndrome?','Trisomy 21',['Monosomy X','Trisomy 13','A deletion on chromosome 5'],'B','Down syndrome usually results from nondisjunction causing three copies of chromosome 21. Monosomy X is Turner syndrome, and a chromosome 5 deletion causes cri-du-chat syndrome.',CAR),
  q(CHR,'A female with a single X chromosome (45,X) has which condition?','Turner syndrome',['Klinefelter syndrome','Down syndrome','Edwards syndrome'],'D','Turner syndrome can cause short stature and ovarian failure. Klinefelter syndrome is 47,XXY in males.',CAR),
  q(CHR,'A male with the karyotype 47,XXY has which condition?','Klinefelter syndrome',['Turner syndrome','Jacobs syndrome','Fragile X syndrome'],'A','The extra X can cause small testes, reduced testosterone and infertility. Jacobs syndrome is 47,XYY.',CAR),
  q(CHR,'What is a karyotype?','A picture of a cell’s chromosomes',['A map of a single gene','A list of a protein’s amino acids','A type of DNA mutation'],'C','Chromosomes are photographed, usually during metaphase, and arranged in pairs by size and banding pattern to detect abnormalities.',CAR),
  q(CHR,'Why do genes located close together on the same chromosome often stay together in offspring?','Crossing over rarely separates them',['They are on different chromosomes','They mutate together','They are always recessive'],'B','Linked genes recombine less often the closer they are. Recombination frequencies are used to build genetic maps.',CAR),
  q(EXP,'Why is Drosophila melanogaster a useful model organism for genetics?','Short generations, many offspring',['It has a very long lifespan','It has thousands of chromosomes','It cannot be bred in a lab'],'D','Fruit flies breed quickly (about 10–14 days), produce many offspring, have few chromosomes and show easily visible traits.',CAR),
  q(EXP,'Which feature makes the worm C. elegans valuable for studying development?','Its transparent body and mapped cells',['Its huge genome','Its ability to fly','Its very long generation time'],'A','Researchers can track every cell as the worm develops, which helped reveal genes controlling programmed cell death.',CAR),
  q(EXP,'Which plant is a widely used model organism in genetics research?','Arabidopsis',['White oak tree','Giant sequoia','Venus flytrap'],'C','Arabidopsis has a small genome, a short life cycle and produces many seeds, making it ideal for plant genetics.',CAR),
  q(EXP,'A student tests how different temperatures affect the number of fruit fly offspring. What is the dependent variable?','The number of offspring',['The temperature','The type of food','The size of the vial'],'B','The dependent variable is what is measured in response to the change. Temperature, which the student changes, is the independent variable.',CAR),
  q(EXP,'What is the purpose of a control group in an experiment?','To provide a baseline for comparison',['To increase the sample size','To test a second hypothesis','To eliminate the need for data'],'D','The control group is treated the same except for the variable being tested, so differences can be attributed to that variable.',CAR),
  q(EXP,'Which statistical test compares observed offspring counts with the counts expected from Mendelian ratios?','Chi-square test',['t-test only','Correlation coefficient','Standard deviation'],'A','The chi-square test shows whether differences between observed and expected results are likely due to chance.',CAR),
  q(EXP,'A dihybrid cross produces four phenotype classes. How many degrees of freedom are used in the chi-square test?','3',['1','2','4'],'C','Degrees of freedom = number of categories − 1 = 4 − 1 = 3. The chi-square value is compared with a table at that number of degrees of freedom.',CAR),
  q(EXP,'Why did Mendel choose pea plants for his experiments?','Distinct traits and controllable crosses',['They reproduce only asexually','They have just one large chromosome','They live for many decades'],'B','Peas show clear either-or traits, have true-breeding lines, grow quickly and can be self- or cross-pollinated.',CAR),
  q(MOL,'A DNA sample contains 30% adenine. What percentage is guanine?','20%',['30%','40%','70%'],'D','A pairs with T, so T = 30%, and A + T = 60%. The remaining 40% is G + C, split evenly: G = 20%.',CAR),
  q(MOL,'Which enzyme makes mRNA using a DNA template?','RNA polymerase',['DNA polymerase','Ligase','Helicase only'],'A','During transcription, RNA polymerase reads the template strand and builds a complementary RNA molecule.',CAR),
  q(MOL,'Where does translation take place?','At ribosomes',['In the nucleus','In the Golgi apparatus','In the lysosome'],'C','Ribosomes read mRNA codons and link amino acids brought by tRNA to build a polypeptide.',CAR),
  q(MOL,'Which codon signals the start of translation and codes for methionine?','AUG',['UAA','UGA','GGG'],'B','AUG is the start codon and sets the reading frame. UAA, UAG and UGA are stop codons that end translation.',CAR),
  q(MOL,'Inserting one extra base into a gene’s coding sequence usually causes:','A frameshift mutation',['A silent mutation','No change to the protein','A chromosome translocation'],'D','Adding or deleting bases (not in multiples of three) shifts the reading frame, changing every codon after it.',CAR),
  q(MOL,'The Meselson-Stahl experiment showed that DNA replication is:','Semiconservative',['Conservative','Dispersive replication','Random'],'A','Each new DNA molecule contains one original strand and one new strand.',CAR),
  q(MOL,'In the lac operon of E. coli, what happens when lactose is present?','The repressor is inactivated, so the genes are transcribed',['The repressor binds tighter, stopping transcription','The operon is deleted','Glucose is produced from DNA'],'C','Lactose (as allolactose) binds the repressor and changes its shape, so it releases the operator and RNA polymerase can transcribe the genes.',CAR),
  q(POP,'In a population, 16% of individuals show a recessive trait (aa). Assuming Hardy-Weinberg equilibrium, what percentage are carriers (Aa)?','48%',['16%','36%','60%'],'D','q² = 0.16, so q = 0.4 and p = 0.6. Carriers = 2pq = 2 × 0.6 × 0.4 = 0.48, or 48%.',CAR),
  q(POP,'Which condition is required for Hardy-Weinberg equilibrium?','Random mating',['Strong natural selection','A very small population','Frequent migration'],'A','Equilibrium also requires a large population, no mutation, no migration (gene flow) and no natural selection.',CAR),
  q(POP,'A few individuals start a new island population, and by chance their allele frequencies differ from the original population. What is this?','Founder effect',['Gene flow','Natural selection','Bottleneck reversal'],'C','The founder effect is a form of genetic drift. It explains why some inherited conditions are more common in isolated populations.',CAR),
  q(POP,'Pollen carried by wind from one population of plants to another introduces new alleles. What is this called?','Gene flow',['Genetic drift','Mutation','Inbreeding'],'B','Gene flow (migration) moves alleles between populations and tends to make them more similar.',CAR),
  q(POP,'Why is the sickle cell allele more common in regions where malaria is widespread?','Heterozygotes are more resistant to malaria',['The allele causes malaria','Homozygotes live longer everywhere','Malaria creates the mutation'],'D','This heterozygote advantage (balancing selection) keeps the allele in the population even though homozygotes have sickle cell disease.',CAR),
  q(MOD,'What does the CRISPR-Cas9 system do?','Cuts DNA at a chosen sequence',['Copies DNA millions of times','Separates DNA fragments by size','Reads the order of amino acids'],'A','A guide RNA directs Cas9 to a matching DNA sequence, where it cuts so genes can be disabled, corrected or inserted.',CAR),
  q(MOD,'Which professional helps families understand genetic test results and inherited risks?','Genetic counselor',['Phlebotomist','Radiologic technologist','Pharmacist'],'C','Genetic counselors have specialized graduate training in genetics and counseling and support informed decision-making.',CAR),
  q(MOD,'What is the purpose of the polymerase chain reaction (PCR)?','To copy a specific DNA segment',['To cut DNA into fragments','To join DNA to plasmids','To translate DNA into protein'],'B','PCR cycles of heating and cooling with primers and a heat-stable DNA polymerase amplify a target sequence exponentially.',CAR),
  q(MOD,'In gel electrophoresis, which DNA fragments travel farthest from the wells?','The smallest fragments',['The largest fragments','The fragments with the most adenine','All fragments travel equally'],'D','DNA is negatively charged and moves toward the positive electrode. Smaller fragments move more easily through the gel.',CAR),
  q(MOD,'What is pharmacogenomics?','Using genes to guide drug choice',['Making drugs from plants','Studying federal drug laws','Growing organs for transplant'],'A','Genetic differences affect how people metabolize drugs. Pharmacogenomic testing helps choose safer, more effective treatments.',CAR)
 ],131)
};
